:::intelligent-ui-html{v="1"}
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  html,body{margin:0;padding:0;height:100%;background:var(--viz-panel);color:var(--viz-text);font-family:system-ui,sans-serif;overflow:hidden;}
  #wrap{position:relative;width:100%;height:100%;}
  canvas{display:block;width:100%;height:100%;}
  .label{position:absolute;bottom:12px;left:0;right:0;text-align:center;font-size:12px;letter-spacing:3px;color:var(--viz-muted);text-transform:uppercase;pointer-events:none;}
</style>
</head>
<body>
<div id="wrap">
  <canvas id="c"></canvas>
  <div class="label">Drag to rotate · auto-spinning</div>
</div>
<script>
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
let W=0,H=0,dpr=1;
function resize(){
  dpr = window.devicePixelRatio || 1;
  W = canvas.clientWidth*dpr;
  H = canvas.clientHeight*dpr;
  canvas.width = W; canvas.height = H;
}
window.addEventListener('resize', resize);
resize();

const LATS=20, LONS=40;
const meridians=[], parallels=[];
function makeSphere(){
  meridians.length=0; parallels.length=0;
  for(let j=0;j<LONS;j++){
    const lon=(j/LONS)*Math.PI*2; const pts=[];
    for(let i=0;i<=LATS;i++){
      const lat=-Math.PI/2+(i/LATS)*Math.PI;
      pts.push({x:Math.cos(lat)*Math.cos(lon), y:Math.sin(lat), z:Math.cos(lat)*Math.sin(lon)});
    }
    meridians.push(pts);
  }
  for(let i=0;i<=LATS;i++){
    const lat=-Math.PI/2+(i/LATS)*Math.PI; const pts=[];
    for(let j=0;j<=LONS;j++){
      const lon=(j/LONS)*Math.PI*2;
      pts.push({x:Math.cos(lat)*Math.cos(lon), y:Math.sin(lat), z:Math.cos(lat)*Math.sin(lon)});
    }
    parallels.push(pts);
  }
}
makeSphere();

let rotX=0.4, rotY=0, drag=false, lastX=0, lastY=0;
canvas.addEventListener('mousedown', e=>{drag=true;lastX=e.clientX;lastY=e.clientY;});
window.addEventListener('mouseup',()=>drag=false);
canvas.addEventListener('mousemove',e=>{
  if(drag){rotY+=(e.clientX-lastX)*0.012;rotX+=(e.clientY-lastY)*0.012;lastX=e.clientX;lastY=e.clientY;}
});
canvas.addEventListener('touchstart',e=>{drag=true;lastX=e.touches[0].clientX;lastY=e.touches[0].clientY;},{passive:true});
window.addEventListener('touchend',()=>drag=false);
canvas.addEventListener('touchmove',e=>{
  if(drag){rotY+=(e.touches[0].clientX-lastX)*0.012;rotX+=(e.touches[0].clientY-lastY)*0.012;lastX=e.touches[0].clientX;lastY=e.touches[0].clientY;}
},{passive:true});

function rotate(p){
  let y=p.y*Math.cos(rotX)-p.z*Math.sin(rotX);
  let z=p.y*Math.sin(rotX)+p.z*Math.cos(rotX);
  let x=p.x;
  const x2=x*Math.cos(rotY)+z*Math.sin(rotY);
  const z2=-x*Math.sin(rotY)+z*Math.cos(rotY);
  return {x:x2,y:y,z:z2};
}
const FOV=720;
function proj(p){
  const r=rotate(p);
  const s=FOV/(FOV+r.z*200);
  return {x:W/2+r.x*200*s, y:H/2+r.y*200*s, z:r.z, s};
}
function drawLine(pts,a0){
  for(let i=0;i<pts.length-1;i++){
    const a=proj(pts[i]), b=proj(pts[i+1]);
    const z=(a.z+b.z)/2;
    const alpha=(z+1)/2*0.85+0.08;
    ctx.strokeStyle=a0+alpha.toFixed(3)+')';
    ctx.lineWidth=(0.4+(z+1)*1.1)*dpr;
    ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();
  }
}

let t=0;
function frame(){
  t+=0.004;
  if(!drag) rotY+=0.006;
  resize();
  // bg clear
  ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--viz-panel').trim()||'#0b0f1a';
  ctx.fillRect(0,0,W,H);

  // central glow
  const cx=W/2,cy=H/2;
  const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,Math.min(W,H)*0.42);
  glow.addColorStop(0,'rgba(90,200,255,0.45)');
  glow.addColorStop(0.35,'rgba(150,110,255,0.22)');
  glow.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=glow;
  ctx.fillRect(0,0,W,H);

  // parallels (latitude rings)
  parallels.forEach((pts,i)=>{
    const lat=-Math.PI/2+(i/LATS)*Math.PI;
    const hue = (Math.abs(lat)<0.15)?'rgba(120,230,255,':'rgba(170,130,255,';
    drawLine(pts,hue);
  });
  // meridians (longitude arcs)
  meridians.forEach(pts=>drawLine(pts,'rgba(210,150,255,'));

  requestAnimationFrame(frame);
}
frame();
</script>
</body>

