<script>
const cv = document.getElementById('c');
const ctx = cv.getContext('2d');
let W, H;
function resize(){ W = cv.width = window.innerWidth; H = cv.height = window.innerHeight - 90; }
window.addEventListener('resize', resize); resize();

const particles = [];
let trails = true, collisions = true;
let mouse = {x:-9999, y:-9999, down:false};

const g = ()=>+document.getElementById('gravity').value;
const sz = ()=>+document.getElementById('size').value;
const el = ()=>+document.getElementById('elastic').value;
const fr = ()=>+document.getElementById('friction').value;
const sp = ()=>+document.getElementById('spawn').value;

function spawn(x,y,n,colorBase){
  for(let i=0;i<n;i++){
    const a = Math.random()*Math.PI*2;
    const speed = 1 + Math.random()*4;
    particles.push({
      x: x + (Math.random()-0.5)*8,
      y: y + (Math.random()-0.5)*8,
      vx: Math.cos(a)*speed,
      vy: Math.sin(a)*speed - 2,
      r: Math.max(2, sz() + (Math.random()-0.5)*2),
      hue: (colorBase + Math.random()*60) % 360
    });
  }
}

function addRandom(n){ for(let i=0;i<n;i++) spawn(Math.random()*W, Math.random()*H*0.4,1,Math.random()*360);
